-- The two checklists published on 2026-11-11: After a Bad Dream Wakes You
-- (Nightmares) and Being the Worst in the Room at Something New (Beginners).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-11`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('after-a-bad-dream-wakes-you', 'After a Bad Dream Wakes You', 'For the minutes after a nightmare wakes you and the room still feels wrong. It puts a low light on, names what is actually in the room, gets you out of bed briefly, keeps you off the clock, and gives the dream a different ending while you are awake.', 'Nightmares', '["Turn on a low light for a minute — the dark keeps a dream feeling present.", "Name five things in the room out loud — the room is the evidence that the dream has ended.", "Get out of bed for ten minutes — lying in the same spot tends to replay it.", "Drink a glass of water standing up — a small ordinary act moves you back into your body.", "Write the dream down in three lines, then shut the book — on paper it stops circling.", "Change which end of the pillow you lie on — a different position breaks the thread.", "Leave the clock alone — knowing the time only adds arithmetic to the fear.", "Give the dream a different ending while awake — rewriting it deliberately takes some charge out of it.", "Tell someone in daylight if it keeps returning — a recurring dream is worth saying out loud."]'::jsonb, 'as needed', array['Sleep', 'Grounding', 'Worry']::text[], 1, '2026-11-11T16:00:00+00:00'::timestamptz),
  ('being-the-worst-in-the-room-at-something-new', 'Being the Worst in the Room at Something New', 'For starting something as an adult and being visibly bad at it. It gets you to say you are new, go six times before judging, record your own progress, ask the question you are embarrassed by, and compare yourself to last month.', 'Beginners', '["Say out loud that you are new — announced beginners get taught, hidden ones get judged.", "Pick a class where you are not the only new one — a room of beginners is kinder than a room of experts.", "Go six times before you decide anything — the first three sessions are noise, not data.", "Record yourself once a month — you cannot feel progress, but you can see it.", "Ask the most basic question you have — the one you are embarrassed by is usually the useful one.", "Compare yourself to last month, not to the best there — they also started somewhere you did not see.", "Practice the part you are worst at for five minutes — the fun part already gets all your time.", "Let one session be genuinely bad — a bad week is not the beginning of quitting.", "Find one person slightly ahead of you — someone two steps up is more use than someone twenty."]'::jsonb, 'weekly', array['Self-Compassion', 'Motivation', 'Perfectionism']::text[], 1, '2026-11-11T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
